class Heap {
  constructor(before) {
    this.items = []
    this.before = before
  }

  get size() {
    return this.items.length
  }

  peek() {
    return this.items[0]
  }

  push(item) {
    const a = this.items
    a.push(item)
    let i = a.length - 1
    while (i > 0) {
      const parent = (i - 1) >> 1
      if (!this.before(a[i], a[parent])) break
      ;[a[i], a[parent]] = [a[parent], a[i]]
      i = parent
    }
  }

  pop() {
    const a = this.items
    const top = a[0]
    const last = a.pop()
    if (a.length) {
      a[0] = last
      let i = 0
      for (;;) {
        const l = 2 * i + 1
        const r = l + 1
        let m = i
        if (l < a.length && this.before(a[l], a[m])) m = l
        if (r < a.length && this.before(a[r], a[m])) m = r
        if (m === i) break
        ;[a[i], a[m]] = [a[m], a[i]]
        i = m
      }
    }
    return top
  }
}

function nearestPoints(points, k) {
  const key = ([x, y]) => [x * x + y * y, x, y]
  const after = (a, b) => {
    const ka = key(a)
    const kb = key(b)
    for (let i = 0; i < 3; i++) if (ka[i] !== kb[i]) return ka[i] > kb[i]
    return false
  }
  // Max-heap: the root is the farthest of the k points kept so far.
  const heap = new Heap(after)
  for (const point of points) {
    heap.push(point)
    if (heap.size > k) heap.pop()
  }
  const result = []
  while (heap.size) result.push(heap.pop())
  return result.reverse()
}

